import{_ as r,o as l,c as x,ag as a,j as s,a as e}from"./chunks/framework.KxDd3USm.js";const E=JSON.parse('{"title":"02.2 E-R 模型 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"02-数据库系统/02-E-R模型.md","filePath":"02-数据库系统/02-E-R模型.md"}'),n={name:"02-数据库系统/02-E-R模型.md"},o={class:"fig"},d={"data-figure-id":"figure-6",viewBox:"0 0 660 380",width:"100%",style:{"max-width":"660px"},role:"img","aria-label":"E-R 图三种基本符号示意。上半部分是三个符号各自的样子：矩形表示实体，内部写实体名，例如学生；椭圆表示属性，内部写属性名，例如姓名；菱形表示联系，内部写联系名，例如选修。下半部分是一个最小的完整 E-R 图：学生与课程两个实体由选修联系相连，学号挂到学生上，课程号挂到课程上，成绩挂在选修菱形上，说明联系也能有自己的属性。"},c={class:"fig"},i={"data-figure-id":"figure-7",viewBox:"0 0 660 400",width:"100%",style:{"max-width":"660px"},role:"img","aria-label":"三种联系类型对比图。第一部分是一对一：一个部门只有一个经理，一个经理只管一个部门，部门到经理之间是一比一。第二部分是一对多：一个部门有多个员工，但一个员工只属于一个部门，部门到员工是一比多。第三部分是多对多：一个学生选多门课，一门课被多个学生选，学生到课程是多对多。结论是只有两端都能对应多个才判多对多。"},h={class:"fig"},g={"data-figure-id":"figure-8",viewBox:"0 0 700 500",width:"100%",style:{"max-width":"700px"},role:"img","aria-label":"案例 B 的完整 E-R 图，分上下两个区域。上半区是强实体之间的联系：系是强实体，有系编号和系名属性；教师是强实体，有教师编号和姓名属性；课程是强实体，有课程号属性。系到教师是一对多联系聘用，系端为1，教师端为n。教师到课程是多对多联系讲授，教师端为m，课程端为n，讲授菱形上挂课时数属性。下半区单独画出弱实体：教研室用双边矩形表示，它有一个本系内编号属性；系与教研室之间用双边菱形表示标识联系设立，系端为1，教研室端为n。教研室自身不能唯一标识自己，必须借用系的主键，所以教研室的主键是系编号加本系内编号的组合键。"},p={class:"fig"},y={"data-figure-id":"figure-9",viewBox:"0 0 660 330",width:"100%",style:{"max-width":"660px"},role:"img","aria-label":"E-R 图转关系模式对照图。左侧是案例 B 的 E-R 图要点：系与教师是一对多联系聘用，教师与课程是多对多联系讲授，讲授上有课时数属性。右侧是转换出的四张关系模式表。系表主键系编号。教师表主键教师编号，外键系编号指向系表。课程表主键课程号。讲授表是单独建的联系表，主键由教师编号与课程号组合而成，另有课时数列。教研室表主键由系编号与自身区分属性本系内编号组合而成。"},u={class:"fig"},_={"data-figure-id":"figure-10",viewBox:"0 0 680 300",width:"100%",style:{"max-width":"680px"},role:"img","aria-label":"E-R 集成时三类冲突示意。属性冲突：同一属性在两图单位不一致，左边零件实体的重量属性用克，右边零件实体的重量属性用千克。命名冲突：左边实体叫教师，右边实体叫教员，名称不同却是同一种对象，属于异名同义。结构冲突：左边把系画成独立实体矩形，右边把系画成教师实体上的一个属性椭圆，同一对象在两张图里形态不同。结论是三类冲突中没有实体冲突这一说法。"};function q(b,t,m,T,w,f){return l(),x("div",null,[t[10]||(t[10]=a('<h1 id="_02-2-e-r-模型-★★★" tabindex="-1">02.2 E-R 模型 ★★★ <a class="header-anchor" href="#_02-2-e-r-模型-★★★" aria-label="Permalink to &quot;02.2 E-R 模型 ★★★&quot;">​</a></h1><p>E-R 模型（<strong>Entity-Relationship Model</strong>，实体-联系模型）是用图形描述现实世界的一种概念模型。案例题第 2 题的第一小问几乎固定考它。</p><h3 id="三个基本要素与术语对照" tabindex="-1">三个基本要素与术语对照 <a class="header-anchor" href="#三个基本要素与术语对照" aria-label="Permalink to &quot;三个基本要素与术语对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名</th><th>英文全称</th><th>符号</th><th>定义</th></tr></thead><tbody><tr><td>实体</td><td>Entity</td><td>矩形</td><td>客观存在、可相互区分的事物；能独立存在</td></tr><tr><td>属性</td><td>Attribute</td><td>椭圆</td><td>实体或联系所具有的性质；本身不能独立存在</td></tr><tr><td>联系</td><td>Relationship</td><td>菱形</td><td>实体之间的关联；依附于实体而存在</td></tr></tbody></table><p><strong>三者的区分靠&quot;能不能独立存在&quot;</strong>：实体是&quot;名词性对象&quot;，能单独拿出来说；属性是贴在实体上的&quot;特征&quot;，脱离实体就没有意义；联系是<strong>连接两个（或多个）实体</strong>的那条关联，它也有自己的属性（如&quot;选修&quot;上的成绩）。考试让你在图上补框时，先问自己&quot;这个词是对象、是特征，还是关系&quot;。</p><p>三个要素的举例：</p><ul><li><strong>实体 Entity</strong>：一名学生、一门课程</li><li><strong>属性 Attribute</strong>：学号、姓名、成绩</li><li><strong>联系 Relationship</strong>：学生&quot;选修&quot;课程</li></ul>',7)),s("figure",o,[(l(),x("svg",d,[...t[0]||(t[0]=[a('<text class="cap" x="110" y="22">实体 Entity</text><rect class="ent" x="55" y="32" width="110" height="48" rx="3"></rect><text class="tt" x="110" y="61">学生</text><text class="capd" x="110" y="98">矩形 · 能独立存在</text><text class="cap" x="330" y="22">属性 Attribute</text><ellipse class="attr" cx="330" cy="56" rx="58" ry="24"></ellipse><text class="tt" x="330" y="61">姓名</text><text class="capd" x="330" y="98">椭圆 · 依附于实体</text><text class="cap" x="550" y="22">联系 Relationship</text><path class="rel" d="M550 32 L606 56 L550 80 L494 56 Z"></path><text class="tt" x="550" y="61">选修</text><text class="capd" x="550" y="98">菱形 · 连接实体</text><line class="div" x1="30" y1="122" x2="630" y2="122"></line><text class="capd" x="330" y="146" style="font-weight:600;fill:var(--faint);letter-spacing:.06em;">完整画法：三要素用线段相连，属性挂在所属的实体或联系上</text><ellipse class="attr" cx="100" cy="196" rx="44" ry="20"></ellipse><text class="at" x="100" y="200">学号</text><path class="ln" d="M100 216 V250"></path><ellipse class="attr" cx="330" cy="176" rx="44" ry="20"></ellipse><text class="at" x="330" y="180">成绩</text><path class="ln" d="M330 196 V250"></path><ellipse class="attr" cx="560" cy="196" rx="50" ry="20"></ellipse><text class="at" x="560" y="200">课程号</text><path class="ln" d="M560 216 V250"></path><rect class="ent" x="52" y="250" width="96" height="46" rx="3"></rect><text class="tts" x="100" y="279">学生</text><path class="ln" d="M148 273 H274"></path><path class="rel" d="M330 250 L386 273 L330 296 L274 273 Z"></path><text class="tts" x="330" y="277">选修</text><path class="ln" d="M386 273 H510"></path><rect class="ent" x="510" y="250" width="100" height="46" rx="3"></rect><text class="tts" x="560" y="279">课程</text><text class="capd" x="330" y="330">成绩只由&quot;谁选了哪门课&quot;决定 → 挂在菱形上，不挂在学生或课程上</text>',32)])])),t[1]||(t[1]=s("figcaption",null,[e("上排是三要素的符号；下排是一个最小完整图——"),s("strong",null,"矩形（实体）＋ 椭圆（属性）＋ 菱形（联系）"),e("，属性用线段挂到它所属的实体或联系上。")],-1))]),t[11]||(t[11]=s("h3",{id:"联系的类型-1-1、1-n、m-n-必须会判",tabindex:"-1"},[e("联系的类型：1:1、1:n、m:n（必须会判） "),s("a",{class:"header-anchor",href:"#联系的类型-1-1、1-n、m-n-必须会判","aria-label":'Permalink to "联系的类型：1:1、1:n、m:n（必须会判）"'},"​")],-1)),t[12]||(t[12]=s("p",null,[e("判法只有一句："),s("strong",null,"站在这端的每一个个体上，问它对面那一端能对应几个"),e('。两边都能对应"多个"才是 m:n。')],-1)),s("figure",c,[(l(),x("svg",i,[...t[2]||(t[2]=[a('<text class="hd" x="24" y="26">① 1:1 一对一</text><text class="nt" x="24" y="45">&quot;一个部门只有一个经理，一个经理只管一个部门&quot;</text><rect class="ent" x="60" y="58" width="92" height="40" rx="3"></rect><text class="tt" x="106" y="83">部门</text><path class="ln" d="M152 78 H184"></path><path class="rel" d="M228 60 L272 78 L228 96 L184 78 Z"></path><text class="rt" x="228" y="82">管理</text><path class="ln" d="M272 78 H348"></path><rect class="ent" x="348" y="58" width="92" height="40" rx="3"></rect><text class="tt" x="394" y="83">经理</text><text class="card" x="176" y="72">1</text><text class="card" x="324" y="72">1</text><text class="nt" x="470" y="72">两端都是 1</text><text class="nt" x="470" y="88">各只有一个</text><line class="div" x1="24" y1="114" x2="636" y2="114"></line><text class="hd" x="24" y="140">② 1:n 一对多</text><text class="nt" x="24" y="159">&quot;一个部门有多个员工，一个员工只属于一个部门&quot;</text><rect class="ent" x="60" y="172" width="92" height="40" rx="3"></rect><text class="tt" x="106" y="197">部门</text><path class="ln" d="M152 192 H184"></path><path class="rel" d="M228 174 L272 192 L228 210 L184 192 Z"></path><text class="rt" x="228" y="196">聘用</text><path class="ln" d="M272 192 H348"></path><rect class="ent" x="348" y="172" width="92" height="40" rx="3"></rect><text class="tt" x="394" y="197">员工</text><text class="card" x="176" y="186">1</text><text class="card" x="324" y="186">n</text><text class="nt" x="470" y="186">部门端是 1、员工端是 n</text><text class="nt" x="470" y="202">只有员工能是&quot;多个&quot;</text><line class="div" x1="24" y1="228" x2="636" y2="228"></line><text class="hd" x="24" y="254">③ m:n 多对多</text><text class="nt" x="24" y="273">&quot;一个学生选多门课，一门课被多个学生选&quot;</text><rect class="ent" x="60" y="286" width="92" height="40" rx="3"></rect><text class="tt" x="106" y="311">学生</text><path class="ln" d="M152 306 H184"></path><path class="rel" d="M228 288 L272 306 L228 324 L184 306 Z"></path><text class="rt" x="228" y="310">选修</text><path class="ln" d="M272 306 H348"></path><rect class="ent" x="348" y="286" width="92" height="40" rx="3"></rect><text class="tt" x="394" y="311">课程</text><text class="card" x="176" y="300">m</text><text class="card" x="324" y="300">n</text><text class="nt" x="470" y="300">两端都是&quot;多个&quot;</text><text class="nt" x="470" y="316">才是 m:n</text>',44)])])),t[3]||(t[3]=s("figcaption",null,[e("三种联系类型的判法只在一句话："),s("strong",null,"站在这端，看对面能对应几个"),e("。①两端都只有 1；②只有一端能多；③两端都能多。")],-1))]),t[13]||(t[13]=a(`<p><strong>反例演示（易错）</strong>：别看到&quot;多个&quot;就判 m:n——<strong>只有两边都能是&quot;多个&quot;才是 m:n</strong>。&quot;一个班有多名学生&quot;但&quot;一名学生只属一个班&quot;是 1:n，不是 m:n。反过来，&quot;一个学生可以选多门课，而一门课只能有一个学生选&quot;这种反常识设定，按定义仍是 1:n——<strong>判定永远按题面给的定义走，不按现实经验</strong>。</p><h3 id="案例-a-图书馆借阅-判联系类型-找联系属性" tabindex="-1">案例 A：图书馆借阅（判联系类型 + 找联系属性） <a class="header-anchor" href="#案例-a-图书馆借阅-判联系类型-找联系属性" aria-label="Permalink to &quot;案例 A：图书馆借阅（判联系类型 + 找联系属性）&quot;">​</a></h3><blockquote><p><strong>业务</strong>：读者凭读者卡借阅图书。一名读者可以借多本书，一本书同时只能被一名读者借走；每笔借阅记录登记借出日期和应还日期。</p><p><strong>要求</strong>：画出 E-R 图，判断联系类型，并把联系上的属性标在正确位置。</p></blockquote><p><strong>审题与推导</strong>：</p><ol><li><strong>找名词 → 实体</strong>：读者、图书。二者都有能唯一标识自己的编号（读者编号、书号），是独立对象，所以都是实体。</li><li><strong>找动词 → 联系</strong>：&quot;借阅&quot;连接读者与图书。</li><li><strong>判类型</strong>：站到<strong>读者</strong>这一端问&quot;一个读者能对应几本书&quot;→ 多本；站到<strong>图书</strong>这一端问&quot;一本书能对应几个读者&quot;→ <strong>同时只能一个</strong>。两端一边多一边单 → <strong>1:n</strong>，多端是读者。</li><li><strong>定属性归属</strong>：&quot;借出日期、应还日期&quot;不是读者的特征，也不是图书的特征——同一本书被不同读者借走时日期不同，同一个读者借不同书时日期也不同。它<strong>只由&quot;谁借了哪本书&quot;这一个组合决定</strong>，所以属于<strong>联系&quot;借阅&quot;</strong>，挂在菱形上。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>              借出日期    应还日期</span></span>
<span class="line"><span>                  \\        /</span></span>
<span class="line"><span>   ┌──────┐        ◇──────◇        ┌──────┐</span></span>
<span class="line"><span>   │ 读者 │───────◇ 借阅  ◇───────│ 图书 │</span></span>
<span class="line"><span>   └──────┘        ◇──────◇        └──────┘</span></span>
<span class="line"><span>       │                                  │</span></span>
<span class="line"><span>    读者编号                             书号</span></span>
<span class="line"><span>      1                                   n</span></span></code></pre></div><p><strong>易错点</strong>：把借出日期画到&quot;图书&quot;实体上。判断方法——<strong>问&quot;这个属性是随实体唯一确定，还是随&#39;这对组合&#39;确定&quot;</strong>：同一本书被两次借阅日期不同，说明它不由书号唯一决定，就不能挂在图书上。</p><h3 id="案例-b-含弱实体的综合场景-考试综合题型" tabindex="-1">案例 B：含弱实体的综合场景（考试综合题型） <a class="header-anchor" href="#案例-b-含弱实体的综合场景-考试综合题型" aria-label="Permalink to &quot;案例 B：含弱实体的综合场景（考试综合题型）&quot;">​</a></h3><blockquote><p><strong>业务</strong>：一所学校有若干<strong>系</strong>，每个系有系编号和系名；一个系聘用多名<strong>教师</strong>，一名教师只属于一个系。一名教师可以讲授多门课，一门课可以由多名教师讲授，<strong>授课</strong>记录该教师讲这门课的课时数。此外，学校为每个系记录其<strong>分教研室</strong>，教研室按&quot;所属系编号 + 本系内编号&quot;区分，不同系的教研室可以同号。</p><p><strong>要求</strong>：画 E-R 图、判断联系类型、生成关系模式。</p></blockquote><p><strong>审题与推导</strong>：</p><ol><li><strong>实体</strong>：系、教师、课程；<strong>弱实体</strong>：教研室。</li><li><strong>联系与类型</strong>：系—教师 = <strong>1:n</strong>（一个系多名教师，一名教师只属一个系）；教师—课程 = <strong>m:n</strong>（讲授）；系—教研室 = <strong>1:n</strong>（一个系有多个教研室，一个教研室只属一个系）。</li><li><strong>弱实体的识别</strong>：题干说教研室按&quot;<strong>所属系编号 + 本系内编号</strong>&quot;区分，不同系可以同号——这说明它<strong>离开&quot;系&quot;就无法被唯一标识</strong>，且它的标识要借用&quot;系&quot;的主键。这就是<strong>弱实体</strong>（Weak Entity）。</li></ol><h3 id="弱实体与属性分类-选择题加分点" tabindex="-1">弱实体与属性分类（选择题加分点） <a class="header-anchor" href="#弱实体与属性分类-选择题加分点" aria-label="Permalink to &quot;弱实体与属性分类（选择题加分点）&quot;">​</a></h3><p><strong>弱实体</strong>：自身属性不足以唯一标识自己，<strong>必须依赖另一个实体（强实体）才能被标识</strong>的存在。画法与转换规则：</p><table tabindex="0"><thead><tr><th></th><th>强实体</th><th>弱实体</th></tr></thead><tbody><tr><td>图形</td><td>普通矩形</td><td><strong>双边矩形</strong></td></tr><tr><td>与强实体的联系</td><td>——</td><td><strong>双边菱形</strong>（标识联系）</td></tr><tr><td>主键</td><td>自身码</td><td><strong>强实体主键 + 自身区分属性</strong>（组合键）</td></tr><tr><td>典型例子</td><td>系、教师</td><td>教研室、订单明细、职工家属</td></tr></tbody></table><p><strong>属性的五种分类</strong>（选择题会问某个属性属于哪类）：</p><table tabindex="0"><thead><tr><th>类别</th><th>含义</th><th>画法 / 例子</th></tr></thead><tbody><tr><td>简单属性</td><td>不可再分</td><td>学号、年龄</td></tr><tr><td>复合属性</td><td>可再分为更小部分</td><td>姓名（姓 + 名）、地址（省 + 市 + 街）</td></tr><tr><td>单值属性</td><td>一个实体只有一个值</td><td>学号、出生日期</td></tr><tr><td>多值属性</td><td>一个实体可有多个值</td><td>电话号码、兴趣；画成<strong>双椭圆</strong></td></tr><tr><td>派生属性</td><td>可由别的属性算出来</td><td>年龄（由出生日期算）；画成<strong>虚线椭圆</strong></td></tr></tbody></table><p><strong>三种以上实体的联系</strong>：当一条联系同时涉及三个及以上实体时叫<strong>多元联系</strong>（如&quot;供应商—零件—项目&quot;三者之间的&quot;供应&quot;联系），判类型时要把&quot;其余实体都固定住&quot;再看本端能有几个。软考以二元联系为主，多元联系了解概念即可。</p>`,17)),s("figure",h,[(l(),x("svg",g,[...t[4]||(t[4]=[a('<text class="zone" x="24" y="20">上半区 · 强实体之间的联系</text><ellipse class="attr" cx="120" cy="46" rx="46" ry="17"></ellipse><text class="at" x="120" y="50">系编号</text><ellipse class="attr" cx="232" cy="46" rx="36" ry="17"></ellipse><text class="at" x="232" y="50">系名</text><path class="ln" d="M120 63 V92"></path><path class="ln" d="M232 63 V92"></path><rect class="ent" x="106" y="92" width="140" height="44" rx="3"></rect><text class="tt" x="176" y="120">系</text><path class="ln" d="M176 136 V160"></path><path class="rel" d="M176 160 L224 178 L176 196 L128 178 Z"></path><text class="rt" x="176" y="182">聘用</text><text class="card" x="196" y="156">1</text><text class="card" x="196" y="210">n</text><rect class="ent" x="106" y="248" width="140" height="44" rx="3"></rect><text class="tt" x="176" y="276">教师</text><path class="ln" d="M176 196 V248"></path><ellipse class="attr" cx="80" cy="200" rx="52" ry="17"></ellipse><text class="at" x="80" y="204">教师编号</text><path class="ln" d="M132 200 H176"></path><ellipse class="attr" cx="286" cy="270" rx="34" ry="17"></ellipse><text class="at" x="286" y="274">姓名</text><path class="ln" d="M246 270 H252"></path><path class="rel" d="M400 190 L452 212 L400 234 L348 212 Z"></path><text class="rt" x="400" y="216">讲授</text><path class="ln" d="M246 268 L348 212"></path><path class="ln" d="M452 212 L560 248"></path><text class="card" x="310" y="238">m</text><text class="card" x="500" y="222">n</text><ellipse class="attr" cx="400" cy="146" rx="42" ry="17"></ellipse><text class="at" x="400" y="150">课时数</text><path class="ln" d="M400 163 V190"></path><rect class="ent" x="490" y="248" width="140" height="44" rx="3"></rect><text class="tt" x="560" y="276">课程</text><ellipse class="attr" cx="560" cy="200" rx="46" ry="17"></ellipse><text class="at" x="560" y="204">课程号</text><path class="ln" d="M560 217 V248"></path><line class="div" x1="24" y1="330" x2="676" y2="330"></line><text class="zone" x="24" y="358">下半区 · 弱实体与标识联系</text><rect class="ent" x="106" y="378" width="140" height="44" rx="3"></rect><text class="tt" x="176" y="406">系</text><path class="lnw" d="M246 400 H326"></path><text class="card" x="272" y="388">1</text><path class="rel" d="M378 378 L430 400 L378 422 L326 400 Z"></path><path class="rel" d="M386 381 L430 399 L386 417 L342 399 Z"></path><text class="rt" x="378" y="404">设立</text><text class="card" x="486" y="388">n</text><path class="lnw" d="M430 400 H540"></path><rect class="ent" x="540" y="372" width="146" height="62" rx="3"></rect><rect class="ent" x="548" y="380" width="130" height="46" rx="2"></rect><text class="tt" x="613" y="409">教研室</text><ellipse class="attr" cx="613" cy="470" rx="56" ry="17"></ellipse><text class="at" x="613" y="474">本系内编号</text><path class="ln" d="M613 440 V453"></path><text class="note" x="24" y="470">教研室自己无法唯一标识</text><text class="note" x="24" y="488">主键 = 系编号 + 本系内编号（借用强实体主键）</text>',56)])])),t[5]||(t[5]=s("figcaption",null,[e("上半区是强实体之间的联系（聘用 1:n、讲授 m:n）；下半区单独画弱实体：教研室用"),s("strong",null,"双边矩形"),e('，它与系之间的标识联系"设立"用'),s("strong",null,"双边菱形"),e("。教研室的主键必须借系的主键，成为组合键。")],-1))]),t[14]||(t[14]=a('<h3 id="e-r-图转关系模式-案例题必考步骤" tabindex="-1">E-R 图转关系模式（案例题必考步骤） <a class="header-anchor" href="#e-r-图转关系模式-案例题必考步骤" aria-label="Permalink to &quot;E-R 图转关系模式（案例题必考步骤）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>联系类型</th><th>转换规则</th></tr></thead><tbody><tr><td>1:1</td><td>联系并入任一端实体（加对方的主键作外键）</td></tr><tr><td>1:n</td><td>联系并入 <strong>n 端</strong>实体（加 1 端的主键作外键）</td></tr><tr><td><strong>m:n</strong></td><td><strong>联系必须单独建一张关系模式</strong>，主键 = 两端主键的组合，联系自身的属性也放这张表</td></tr><tr><td>弱实体</td><td>单独建表，主键 = <strong>强实体主键 + 自身区分属性</strong></td></tr></tbody></table><p><strong>反例演示（易错）</strong>：学生-课程是 m:n，若把&quot;选课&quot;并入学生表（学生表加课程号、成绩列），一个学生选多门课就要占多行，学号、姓名重复存储，而且学号不再能作主键——错。<strong>口诀：多对多，单独坐一桌</strong>。</p>',3)),s("figure",p,[(l(),x("svg",y,[...t[6]||(t[6]=[a('<text class="hd" x="24" y="26">E-R 图要点</text><rect class="bxa" x="24" y="38" width="200" height="34" rx="7"></rect><text class="mono" x="38" y="59">系 ――1:n―― 教师</text><text class="mn" x="38" y="88">联系名：聘用</text><rect class="bxg" x="24" y="102" width="200" height="34" rx="7"></rect><text class="mono" x="38" y="123">教师 ――m:n―― 课程</text><text class="mn" x="38" y="152">联系名：讲授（含课时数）</text><path class="arw" d="M240 100 H290"></path><path class="arw" d="M280 92 L290 100 L280 108"></path><text class="tag" x="246" y="90">按规则转换</text><text class="hd" x="310" y="26">转换出的关系模式</text><rect class="bxa" x="310" y="38" width="326" height="40" rx="7"></rect><text class="mono" x="324" y="56">系(系编号, 系名)</text><text class="tag" x="324" y="71">主键：系编号</text><rect class="bxa" x="310" y="86" width="326" height="56" rx="7"></rect><text class="mono" x="324" y="104">教师(教师编号, 姓名, 系编号)</text><text class="tag" x="324" y="119">主键：教师编号　外键：系编号 → 系</text><text class="mn" x="324" y="134">1:n 把 1 端主键并入 n 端</text><rect class="bxa" x="310" y="150" width="326" height="40" rx="7"></rect><text class="mono" x="324" y="168">课程(课程号, 课程名)</text><text class="tag" x="324" y="183">主键：课程号</text><rect class="bxg" x="310" y="198" width="326" height="56" rx="7"></rect><text class="mono" x="324" y="216">讲授(教师编号, 课程号, 课时数)</text><text class="tag" x="324" y="231">主键：(教师编号, 课程号) 组合键</text><text class="tagg" x="324" y="246">m:n 单独建表，联系属性放这里</text><rect class="bxa" x="310" y="262" width="326" height="56" rx="7"></rect><text class="mono" x="324" y="280">教研室(系编号, 本系内编号, 教研室名)</text><text class="tag" x="324" y="295">主键：(系编号, 本系内编号) 组合键</text><text class="tag" x="324" y="310">弱实体：主键借用强实体的主键</text>',29)])])),t[7]||(t[7]=s("figcaption",null,[e("左图的每条联系，按类型走对应规则落到右边的表。"),s("strong",null,"1:n 把 1 端主键并入 n 端；m:n 单独建表且联系属性跟过去；弱实体的主键借用强实体主键。")],-1))]),t[15]||(t[15]=a('<p><strong>案例 B 的完整转换结果</strong>：</p><table tabindex="0"><thead><tr><th>关系模式</th><th>主键</th><th>外键 / 说明</th></tr></thead><tbody><tr><td>系(系编号, 系名)</td><td>系编号</td><td>——</td></tr><tr><td>教师(教师编号, 姓名, 系编号)</td><td>教师编号</td><td>系编号 → 系（1:n 并入 n 端）</td></tr><tr><td>课程(课程号, 课程名)</td><td>课程号</td><td>——</td></tr><tr><td>讲授(教师编号, 课程号, 课时数)</td><td>(教师编号, 课程号)</td><td>两列分别 → 教师、课程（m:n 单独建表）</td></tr><tr><td>教研室(系编号, 本系内编号, 教研室名)</td><td>(系编号, 本系内编号)</td><td>系编号 → 系（弱实体借用强实体主键）</td></tr></tbody></table><p><strong>注意&quot;聘用&quot;联系没有单独建表</strong>：它是 1:n，已被&quot;并入 n 端&quot;消化掉了——如果考试让你写&quot;聘用&quot;表，那是错的。</p><h3 id="e-r-集成时的三类冲突-选择题考过" tabindex="-1">E-R 集成时的三类冲突（选择题考过） <a class="header-anchor" href="#e-r-集成时的三类冲突-选择题考过" aria-label="Permalink to &quot;E-R 集成时的三类冲突（选择题考过）&quot;">​</a></h3><p>多个分 E-R 图合并时会撞车：</p><ul><li><strong>属性冲突</strong>：同一属性在不同分图里<strong>类型或单位不一致</strong>（这边&quot;重量&quot;用克、那边用千克）。</li><li><strong>命名冲突</strong>：<strong>同名异义</strong>（都叫&quot;编号&quot;但一个指学生号一个指课程号）或<strong>异名同义</strong>（&quot;教师&quot;与&quot;教员&quot;指同一种人）。</li><li><strong>结构冲突</strong>：同一对象在<strong>此图是实体、在彼图却成了属性</strong>（这边&quot;系&quot;是独立实体，那边只是&quot;教师&quot;的一个属性）。</li></ul><p><strong>没有&quot;实体冲突&quot;这种说法</strong>——选项里出现即排除。三种冲突里，<strong>最容易考的是结构冲突</strong>，因为它必须改变 E-R 图的结构才能消除，而命名冲突只需统一命名。</p>',7)),s("figure",u,[(l(),x("svg",_,[...t[8]||(t[8]=[a('<text class="hd" x="24" y="22">① 属性冲突：同属性、单位或类型不一致</text><rect class="ent" x="40" y="38" width="76" height="32" rx="3"></rect><text class="tt" x="78" y="59">零件</text><ellipse class="attr" cx="186" cy="54" rx="48" ry="17"></ellipse><text class="at" x="186" y="58">重量（克）</text><path class="ln" d="M116 54 H138"></path><rect class="ent" x="300" y="38" width="76" height="32" rx="3"></rect><text class="tt" x="338" y="59">零件</text><ellipse class="attr" cx="446" cy="54" rx="58" ry="17"></ellipse><text class="at" x="446" y="58">重量（千克）</text><path class="ln" d="M376 54 H388"></path><text class="bad" x="524" y="50">同一属性，</text><text class="bad" x="524" y="66">两边单位不同</text><line class="div" x1="24" y1="96" x2="656" y2="96"></line><text class="hd" x="24" y="120">② 命名冲突：同名异义 / 异名同义</text><rect class="ent" x="40" y="136" width="76" height="32" rx="3"></rect><text class="tt" x="78" y="157">教师</text><rect class="ent" x="180" y="136" width="76" height="32" rx="3"></rect><text class="tt" x="218" y="157">教员</text><text class="bad" x="284" y="152">名称不同，却是同一种对象</text><text class="bad" x="284" y="168">→ 异名同义（同义要统一命名）</text><line class="div" x1="24" y1="196" x2="656" y2="196"></line><text class="hd" x="24" y="220">③ 结构冲突：同一对象，此图是实体、彼图是属性</text><rect class="ent" x="40" y="236" width="76" height="32" rx="3"></rect><text class="tt" x="78" y="257">系</text><text class="small" x="40" y="288">分图一：系是独立实体</text><rect class="ent" x="290" y="236" width="76" height="32" rx="3"></rect><text class="tt" x="328" y="257">教师</text><ellipse class="attr" cx="452" cy="252" rx="52" ry="17"></ellipse><text class="at" x="452" y="256">系名</text><path class="ln" d="M366 252 H400"></path><text class="small" x="290" y="288">分图二：系只是教师的属性</text><text class="bad" x="536" y="248">必须改动结构</text><text class="bad" x="536" y="264">才能消除</text>',34)])])),t[9]||(t[9]=s("figcaption",null,[e("三类冲突各有可检验的判断点："),s("strong",null,'属性冲突看单位/类型，命名冲突看"是否同一对象"，结构冲突看"实体还是属性"'),e('。没有"实体冲突"。')],-1))])])}const R=r(n,[["render",q]]);export{E as __pageData,R as default};
